import { useDispatch } from "react-redux";
import "./AddUser.css";
import { addUser } from "../../store/actions/userActions";
import { collectUsers } from "../../helpers/collectUsers";
import { useState } from "react";

const AddUser = () => {
  const dispatch = useDispatch();

  const [user, setUser] = useState([]);

  const collectUsers = (data) => {
    e.preventDefault()
    const userX = {
      name: data.name.value,
      surname: data.sName.value,
      age: data.age.value,
      // file: URL.createObjectURL(data.file.files[0]),
    };
    setUser([...user, userX]);
    console.log(user);

  };


  console.log();

  return (
    <div>
      <form
        onSubmit={(e) => {
          collectUsers(e.target.elements);
          // e.preventDefault();
          // dispatch(addUser(collectUsers(e.target.elements)));
          // e.target.reset();
        }}
      >
        <input type="text" className="text" placeholder="Name" id="name" />
        <input type="text" className="text" placeholder="Surname" id="sName" />
        <input type="text" className="text" placeholder="Age" id="age" />
        <label>
          Choose your best photo 😉
          <input type="file" className="file" id="file" />
        </label>
        <input type="submit" />
      </form>
    </div>
  );
};

export default AddUser;
